    const n = big ? 100000 : r.int(3, 8);
    const lab = r.shuffle(Array.from({ length: n }, (_, i) => i));
    const edges = [], has = new Set();
    const key = (a, b) => Math.min(a, b) + "," + Math.max(a, b);
    for (let i = 1; i < n; i++) {
      const e = [lab[i], lab[r.int(Math.max(0, i - 4), i - 1)]]; // a random, fairly deep tree
      edges.push(e); has.add(key(e[0], e[1]));
    }
    for (;;) {
      const a = r.int(0, n - 1), b = r.int(0, n - 1);
      if (a !== b && !has.has(key(a, b))) { edges.push([a, b]); break; }
    }
    return [r.shuffle(edges.map(e => (r.bool() ? e : [e[1], e[0]])))];
  }

