function extraCable(edges: number[][]): number[] {
  const n = edges.length;
  for (let skip = n - 1; skip >= 0; skip--) {
    const adj: number[][] = Array.from({ length: n }, () => []);
    edges.forEach(([a, b], i) => { if (i !== skip) { adj[a].push(b); adj[b].push(a); } });
    const seen = new Array(n).fill(false);
    seen[0] = true;
    const queue = [0];
    for (let head = 0; head < queue.length; head++)
      for (const v of adj[queue[head]])
        if (!seen[v]) { seen[v] = true; queue.push(v); }
    if (queue.length === n) return edges[skip]; // n − 1 cables reaching everyone: a tree
  }
  return [];
}

