class Solution:
    def extraCable(self, edges: List[List[int]]) -> List[int]:
        n = len(edges)
        for skip in range(n - 1, -1, -1):
            adj = [[] for _ in range(n)]
            for i, (a, b) in enumerate(edges):
                if i != skip:
                    adj[a].append(b)
                    adj[b].append(a)
            seen = [False] * n
            seen[0] = True
            stack, reached = [0], 1
            while stack:
                for v in adj[stack.pop()]:
                    if not seen[v]:
                        seen[v] = True
                        reached += 1
                        stack.append(v)
            if reached == n:  # n - 1 cables reaching everyone: a tree
                return edges[skip]
        return []

